// src/components/PurchaseOrder/PurchaseOrderRegistrationForm.jsx
import React, { useState } from "react";
import { Box, Typography, TextField, Button, Stack } from "@mui/material";
import { useLocation, useNavigate } from "react-router-dom";
import { createPurchaseOrder, updatePurchaseOrder } from "../../services/purchaseOrderApi";
import UserSearchModal from "../User/UserSearchModal";
import PartnerSearchModal from "../Partner/PartnerSearchModal";
import ItemSearchModal from "../Item/ItemSearchModal";

const PurchaseOrderRegistrationForm = () => {
  const location = useLocation();
  const navigate = useNavigate();

  // mode: "edit"이면 수정, 아니면 신규 등록
  const initData =
    location.state && location.state.mode === "edit" ? location.state : null;
  const isEditMode = !!initData;

  // 헤더 필드 상태
  const [buyerId, setBuyerId] = useState(initData?.buyerId || "");
  const [buyerName, setBuyerName] = useState(initData?.buyerName || "");
  const [supplierId, setSupplierId] = useState(initData?.supplierId || "");
  const [supplierName, setSupplierName] = useState(initData?.supplierName || "");
  const [dueDate, setDueDate] = useState(
    initData?.dueDate ? initData.dueDate.split("T")[0] : ""
  );
  const [warehouseLocation, setWarehouseLocation] = useState(initData?.warehouseLocation || "");
  const [note, setNote] = useState(initData?.note || "");

  // 품목 정보
  const [itemCode, setItemCode] = useState(initData?.itemCode || "");
  const [itemName, setItemName] = useState(initData?.itemName || "");
  const [unitCode, setUnitCode] = useState(initData?.unitCode || "");
  const [quantity, setQuantity] = useState(
    initData?.quantity !== null && initData?.quantity !== undefined ? initData.quantity : 0
  );

  // 모달 제어 상태
  const [openUserModal, setOpenUserModal] = useState(false);
  const [openPartnerModal, setOpenPartnerModal] = useState(false);
  const [openItemModal, setOpenItemModal] = useState(false);

  // 모달 선택 후 콜백
  const handleSelectUser = (selected) => {
    // 예: { id: 2, username: "superadmin", ... }
    setBuyerId(selected.id);
    setBuyerName(selected.username);
    setOpenUserModal(false);
  };

  const handleSelectPartner = (selected) => {
    // 예: { id: 1, partnerName: "드림월드", ... }
    setSupplierId(selected.id);
    setSupplierName(selected.partnerName);
    setOpenPartnerModal(false);
  };

  const handleSelectItem = (selected) => {
    // 예: { id: 1, itemCode: "ITEM001", itemName: "사과", unit: "EA", ... }
    setItemCode(selected.itemCode);
    setItemName(selected.itemName);
    setUnitCode(selected.unit);
    setOpenItemModal(false);
  };

  const handleSubmit = async () => {
    const data = {
      buyerId: buyerId ? Number(buyerId) : null,
      buyerName,
      supplierId: supplierId ? Number(supplierId) : null,
      supplierName,
      dueDate: dueDate || null,
      warehouseLocation,
      note,
      itemCode,
      itemName,
      unitCode,
      quantity: quantity === null || quantity === "" ? 0 : Number(quantity),
    };

    try {
      if (isEditMode) {
        await updatePurchaseOrder(initData.id, data);
        alert("발주 수정 완료");
      } else {
        await createPurchaseOrder(data);
        alert("발주 등록 완료");
      }
      navigate("/purchase-order/search");
    } catch (err) {
      alert("에러 발생: " + err.message);
    }
  };

  return (
    <Box sx={{ width: "100%", height: "100%", backgroundColor: "#e0e0e0", p: 2 }}>
      <Box
        sx={{
          backgroundColor: "#fff",
          p: 2,
          borderRadius: 2,
          border: "1px solid #ddd",
          maxWidth: 600,
          margin: "0 auto",
        }}
      >
        <Typography variant="h6" sx={{ mb: 2 }}>
          {isEditMode ? "발주 수정" : "발주 등록"}
        </Typography>

        <Stack direction="row" spacing={2} sx={{ mb: 2 }}>
          <Stack spacing={1}>
            <Typography variant="body2">발주자</Typography>
            <Stack direction="row" spacing={1}>
              <TextField
                label="발주자ID"
                size="small"
                value={buyerId}
                onChange={(e) => setBuyerId(e.target.value)}
                onDoubleClick={() => setOpenUserModal(true)}
                sx={{ width: 100 }}
              />
              <TextField
                label="발주자"
                size="small"
                value={buyerName}
                onChange={(e) => setBuyerName(e.target.value)}
                onDoubleClick={() => setOpenUserModal(true)}
                sx={{ width: 100 }}
              />
            </Stack>
          </Stack>
          <Stack spacing={1}>
            <Typography variant="body2">발주처</Typography>
            <Stack direction="row" spacing={1}>
              <TextField
                label="발주처ID"
                size="small"
                value={supplierId}
                onChange={(e) => setSupplierId(e.target.value)}
                onDoubleClick={() => setOpenPartnerModal(true)}
                sx={{ width: 100 }}
              />
              <TextField
                label="발주처"
                size="small"
                value={supplierName}
                onChange={(e) => setSupplierName(e.target.value)}
                onDoubleClick={() => setOpenPartnerModal(true)}
                sx={{ width: 100 }}
              />
            </Stack>
          </Stack>
        </Stack>

        <Stack direction="row" spacing={2} sx={{ mb: 2 }}>
          <Stack spacing={1}>
            <Typography variant="body2">납기일자</Typography>
            <TextField
              type="date"
              size="small"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
              sx={{ width: 150 }}
              InputLabelProps={{ shrink: true }}
            />
          </Stack>
          <Stack spacing={1}>
            <Typography variant="body2">입고장소</Typography>
            <TextField
              size="small"
              value={warehouseLocation}
              onChange={(e) => setWarehouseLocation(e.target.value)}
              sx={{ width: 150 }}
            />
          </Stack>
        </Stack>

        <Stack spacing={1} sx={{ mb: 2 }}>
          <Typography variant="body2">비고</Typography>
          <TextField
            multiline
            rows={2}
            size="small"
            value={note}
            onChange={(e) => setNote(e.target.value)}
          />
        </Stack>

        <Typography variant="subtitle1" sx={{ mt: 2 }}>
          품목 정보
        </Typography>
        <Stack direction="row" spacing={2} sx={{ mb: 2 }}>
          <TextField
            label="품목코드"
            size="small"
            value={itemCode}
            onChange={(e) => setItemCode(e.target.value)}
            sx={{ width: 120 }}
          />
          <TextField
            label="품목명"
            size="small"
            value={itemName}
            onChange={(e) => setItemName(e.target.value)}
            onDoubleClick={() => setOpenItemModal(true)}
            sx={{ width: 160 }}
          />
          <TextField
            label="단위"
            size="small"
            value={unitCode}
            onChange={(e) => setUnitCode(e.target.value)}
            sx={{ width: 80 }}
          />
          <TextField
            label="수량"
            size="small"
            type="number"
            value={quantity}
            onChange={(e) => setQuantity(e.target.value)}
            sx={{ width: 80 }}
          />
        </Stack>

        <Button variant="contained" onClick={handleSubmit}>
          {isEditMode ? "수정" : "등록"}
        </Button>
      </Box>

      {/* 모달 컴포넌트 */}
      <UserSearchModal
        open={openUserModal}
        onClose={() => setOpenUserModal(false)}
        onSelect={handleSelectUser}
        placeholder="발주자 검색"
      />
      <PartnerSearchModal
        open={openPartnerModal}
        onClose={() => setOpenPartnerModal(false)}
        onSelect={handleSelectPartner}
        placeholder="발주처 검색"
      />
      <ItemSearchModal
        open={openItemModal}
        onClose={() => setOpenItemModal(false)}
        onSelect={handleSelectItem}
        placeholder="품목 검색"
      />
    </Box>
  );
};

export default PurchaseOrderRegistrationForm;
