// src/context/GlobalContext.js
import React, { createContext, useContext, useState } from "react";

const GlobalContext = createContext();

export const useGlobalState = () => {
  return useContext(GlobalContext);
};

export const GlobalProvider = ({ children }) => {
  const [attendanceData, setAttendanceData] = useState([]);
  const [employeeData, setEmployeeData] = useState([]);
  const [attendanceStatus, setAttendanceStatus] = useState([]);
  const [partnerData, setPartnerData] = useState([]);
  const [orderData, setOrderData] = useState([]); // PurchaseOrder 관련 데이터도 이 이름으로 사용하거나 별도 변수로 변경
  const [paymentData, setPaymentData] = useState([]);
  const [shipmentData, setShipmentData] = useState([]);
  const [inspectionData, setInspectionData] = useState([]);

  // 선택된 주문(디테일과 주문 진행현황) 상태
  const [selectedOrder, setSelectedOrder] = useState(null);

  // 추가: 발주(주문) 등록폼 상태 (글로벌로 보관)
  const [registrationFormData, setRegistrationFormData] = useState({
    buyerId: "",
    buyerName: "",
    supplierId: "",
    supplierName: "",
    dueDate: "",
    warehouseLocation: "",
    // DataGrid용 품목 데이터 (초기 3행)
    rows: [
      { id: 1, itemCode: "", itemName: "", unit: "", quantity: 0 },
      { id: 2, itemCode: "", itemName: "", unit: "", quantity: 0 },
      { id: 3, itemCode: "", itemName: "", unit: "", quantity: 0 },
    ],
  });

  return (
    <GlobalContext.Provider
      value={{
        attendanceData,
        setAttendanceData,
        employeeData,
        setEmployeeData,
        attendanceStatus,
        setAttendanceStatus,
        partnerData,
        setPartnerData,
        orderData,
        setOrderData,
        paymentData,
        setPaymentData,
        shipmentData,
        setShipmentData,
        inspectionData,    
        setInspectionData,
        selectedOrder,
        setSelectedOrder,
        registrationFormData,        // 추가된 등록폼 상태
        setRegistrationFormData,     // 등록폼 상태 업데이트 함수
      }}
    >
      {children}
    </GlobalContext.Provider>
  );
};
